    global: 'Program';
    module: 'Program';
    function: 'FunctionDeclaration' | 'FunctionExpression' | 'ArrowFunctionExpression';
    'function-expression-name': 'FunctionExpression';
    block: 'BlockStatement';
    catch: 'CatchClause';
    class: 'ClassDeclaration' | 'ClassExpression';
