    eslintUsed?: boolean;
    eslintExported?: boolean;
    eslintExplicitGlobal?: boolean;
    eslintImplicitGlobalSetting?: 'readonly' | 'writable' | 'off';
    eslintExplicitGlobalComments?: Comment[];
};
