type SelectedVisitor = { visit(node: Node): void }['visit'];
export type LegacyListener = {
    [Event in NodeEvent]?: (node: Node<EventKind<Event>>) => void;
} & PathListeners & {
    [selector: string]:
            | SelectedVisitor
            | { visit(comment: Comment): void }['visit']
            | PathListeners[PathEvent]
            | undefined;
